30	/**
31	 * This class constructs a Merkle tree that provides one checksum for all data within a container.
32	 *
33	 * As the leaves of the tree, a checksum for each chunk is computed by taking a checksum of all checksums within that
34	 * chunk. Each chunk checksum in a block is further checksummed together to generate the block level checksum. Finally,
35	 * The checksums of all blocks are checksummed together to create a container level checksum.
36	 * Note that checksums are order dependent. Chunk checksums are sorted by their
37	 * offset within a block, and block checksums are sorted by their block ID.
38	 *
39	 * This class can be used to construct a consistent and completely filled {@link ContainerProtos.ContainerMerkleTree}
40	 * object. It allows building a container merkle tree from scratch by incrementally adding chunks.
41	 * The final checksums above the leaf levels of the tree are not calculated until
42	 * {@link ContainerMerkleTreeWriter#toProto} is called.
43	 */
44	public class ContainerMerkleTreeWriter {
45	
46	  private final SortedMap<Long, BlockMerkleTreeWriter> id2Block;
47	  // All merkle tree generation will use CRC32C to aggregate checksums at each level, regardless of the
48	  // checksum algorithm used on the underlying data.
49	  public static final Supplier<ChecksumByteBuffer> CHECKSUM_BUFFER_SUPPLIER = ChecksumByteBufferFactory::crc32CImpl;
50	
51	  /**
52	   * Constructs an empty Container merkle tree object.
53	   */
54	  public ContainerMerkleTreeWriter() {
55	    id2Block = new TreeMap<>();
56	  }
57	
58	  /**
59	   * Adds chunks to a block in the tree. The block entry will be created if it is the first time adding chunks to it.
60	   * If the block entry already exists, the chunks will be added to the existing chunks for that block.
61	   *
62	   * @param blockID The ID of the block that these chunks belong to.
63	   * @param chunks A list of chunks to add to this block. The chunks will be sorted internally by their offset.
64	   */
65	  public void addChunks(long blockID, Collection<ContainerProtos.ChunkInfo> chunks) {
66	    id2Block.computeIfAbsent(blockID, BlockMerkleTreeWriter::new).addChunks(chunks);
67	  }
68	
69	  /**
70	   * Uses chunk hashes to compute all remaining hashes in the tree, and returns it as a protobuf object. No checksum
71	   * computation for the tree happens outside of this method.
72	   *
73	   * @return A complete protobuf object representation of this tree.
74	   */
75	  public ContainerProtos.ContainerMerkleTree toProto() {
76	    // Compute checksums and return the result.
77	    ContainerProtos.ContainerMerkleTree.Builder containerTreeBuilder = ContainerProtos.ContainerMerkleTree.newBuilder();
78	    ChecksumByteBuffer checksumImpl = CHECKSUM_BUFFER_SUPPLIER.get();
79	    ByteBuffer containerChecksumBuffer = ByteBuffer.allocate(Long.BYTES * id2Block.size());
80	
81	    for (BlockMerkleTreeWriter blockTree: id2Block.values()) {
82	      ContainerProtos.BlockMerkleTree blockTreeProto = blockTree.toProto();
83	      containerTreeBuilder.addBlockMerkleTree(blockTreeProto);
84	      // Add the block's checksum to the buffer that will be used to calculate the container checksum.
85	      containerChecksumBuffer.putLong(blockTreeProto.getDataChecksum());
86	    }
87	    containerChecksumBuffer.flip();
88	    checksumImpl.update(containerChecksumBuffer);
89	
90	    return containerTreeBuilder
91	        .setDataChecksum(checksumImpl.getValue())
92	        .build();
93	  }
94	
95	  /**
96	   * Constructs a merkle tree for a single block within a container.
97	   */
98	  private static class BlockMerkleTreeWriter {
99	    // Map of each offset within the block to its chunk info.
100	    // Chunk order in the checksum is determined by their offset.
101	    private final SortedMap<Long, ChunkMerkleTreeWriter> offset2Chunk;
102	    private final long blockID;
103	
104	    BlockMerkleTreeWriter(long blockID) {
105	      this.blockID = blockID;
106	      this.offset2Chunk = new TreeMap<>();
107	    }
108	
109	    /**
110	     * Adds the specified chunks to this block. The offset value of the chunk must be unique within the block,
111	     * otherwise it will overwrite the previous value at that offset.
112	     *
113	     * @param chunks A list of chunks to add to this block.
114	     */
115	    public void addChunks(Collection<ContainerProtos.ChunkInfo> chunks) {
116	      for (ContainerProtos.ChunkInfo chunk: chunks) {
117	        offset2Chunk.put(chunk.getOffset(), new ChunkMerkleTreeWriter(chunk));
118	      }
119	    }
120	
121	    /**
122	     * Uses chunk hashes to compute a block hash for this tree, and returns it as a protobuf object. All block checksum
123	     * computation for the tree happens within this method.
124	     *
125	     * @return A complete protobuf object representation of this block tree.
126	     */
127	    public ContainerProtos.BlockMerkleTree toProto() {
128	      ContainerProtos.BlockMerkleTree.Builder blockTreeBuilder = ContainerProtos.BlockMerkleTree.newBuilder();
129	      ChecksumByteBuffer checksumImpl = CHECKSUM_BUFFER_SUPPLIER.get();
130	      ByteBuffer blockChecksumBuffer = ByteBuffer.allocate(Long.BYTES * offset2Chunk.size());
131	
132	      for (ChunkMerkleTreeWriter chunkTree: offset2Chunk.values()) {
133	        // Ordering of checksums within a chunk is assumed to be in the order they are written.
134	        // This assumption is already built in to the code that reads and writes the values (see
135	        // ChunkInputStream#validateChunk for an example on the client read path).
136	        // There is no other value we can use to sort these checksums, so we assume the stored proto has them in the
137	        // correct order.
138	        ContainerProtos.ChunkMerkleTree chunkTreeProto = chunkTree.toProto();
139	        blockTreeBuilder.addChunkMerkleTree(chunkTreeProto);
140	        blockChecksumBuffer.putLong(chunkTreeProto.getDataChecksum());
141	      }
142	      blockChecksumBuffer.flip();
143	      checksumImpl.update(blockChecksumBuffer);
144	
145	      return blockTreeBuilder
146	          .setBlockID(blockID)
147	          .setDataChecksum(checksumImpl.getValue())
148	          .build();
149	    }
150	  }
