55	 * Class that manages Containers created on the datanode.
56	 */
57	public class ContainerSet implements Iterable<Container<?>> {
58	
59	  private static final Logger LOG = LoggerFactory.getLogger(ContainerSet.class);
60	
61	  private final ConcurrentSkipListMap<Long, Container<?>> containerMap = new
62	      ConcurrentSkipListMap<>();
63	  private final ConcurrentSkipListSet<Long> missingContainerSet =
64	      new ConcurrentSkipListSet<>();
65	  private final ConcurrentSkipListMap<Long, Long> recoveringContainerMap =
66	      new ConcurrentSkipListMap<>();
67	  private Clock clock;
68	  private long recoveringTimeout;
69	  private final Table<Long, String> containerIdsTable;
70	  // Handler that will be invoked when a scan of a container in this set is requested.
71	  private Consumer<Container<?>> containerScanHandler;
72	
