82	  public ContainerSet(Table<Long, String> continerIdsTable, long recoveringTimeout, boolean readOnly) {
83	    this.clock = Clock.system(ZoneOffset.UTC);
84	    this.containerIdsTable = continerIdsTable;
85	    this.recoveringTimeout = recoveringTimeout;
86	    if (!readOnly && containerIdsTable == null) {
87	      throw new IllegalArgumentException("Container table cannot be null when container set is not read only");
88	    }
89	  }
