105	  /**
106	   * Add Container to container map. This would fail if the container is already present or has been marked as missing.
107	   * @param container container to be added
108	   * @return If container is added to containerMap returns true, otherwise
109	   * false
110	   */
111	  public boolean addContainer(Container<?> container) throws StorageContainerException {
112	    return addContainer(container, false);
113	  }
