116	   * Add Container to container map. This would overwrite the container even if it is missing. But would fail if the
117	   * container is already present.
118	   * @param container container to be added
119	   * @return If container is added to containerMap returns true, otherwise
120	   * false
121	   */
122	  public boolean addContainerByOverwriteMissingContainer(Container<?> container) throws StorageContainerException {
123	    return addContainer(container, true);
124	  }
