126	  public void ensureContainerNotMissing(long containerId, State state) throws StorageContainerException {
127	    if (missingContainerSet.contains(containerId)) {
128	      throw new StorageContainerException(String.format("Container with container Id %d with state : %s is missing in" +
129	          " the DN.", containerId, state),
130	          ContainerProtos.Result.CONTAINER_MISSING);
131	    }
132	  }
