134	  /**
135	   * @param scanner A callback that will be invoked when a scan of a container in this set is requested.
136	   */
137	  public void registerContainerScanHandler(Consumer<Container<?>> scanner) {
138	    this.containerScanHandler = scanner;
139	  }
140	
141	  /**
142	   * Triggers a scan of a container in this set using the registered scan handler. This is a no-op if no scan handler
143	   * is registered or the container does not exist in the set.
144	   * @param containerID The container in this set to scan.
145	   */
146	  public void scanContainer(long containerID) {
147	    if (containerScanHandler != null) {
148	      Container<?> container = getContainer(containerID);
149	      if (container != null) {
150	        containerScanHandler.accept(container);
151	      } else {
152	        LOG.warn("Request to scan container {} which was not found in the container set", containerID);
153	      }
154	    }
155	  }
156	
157	  /**
158	   * Add Container to container map.
159	   * @param container container to be added
160	   * @param overwrite if true should overwrite the container if the container was missing.
161	   * @return If container is added to containerMap returns true, otherwise
162	   * false
163	   */
164	  private boolean addContainer(Container<?> container, boolean overwrite) throws
165	      StorageContainerException {
166	    Preconditions.checkNotNull(container, "container cannot be null");
167	
168	    long containerId = container.getContainerData().getContainerID();
169	    State containerState = container.getContainerData().getState();
170	    if (!overwrite) {
171	      ensureContainerNotMissing(containerId, containerState);
172	    }
173	    if (containerMap.putIfAbsent(containerId, container) == null) {
174	      if (LOG.isDebugEnabled()) {
175	        LOG.debug("Container with container Id {} is added to containerMap",
176	            containerId);
177	      }
178	      try {
179	        if (containerIdsTable != null) {
180	          containerIdsTable.put(containerId, containerState.toString());
181	        }
182	      } catch (IOException e) {
183	        throw new StorageContainerException(e, ContainerProtos.Result.IO_EXCEPTION);
184	      }
185	      missingContainerSet.remove(containerId);
186	      // wish we could have done this from ContainerData.setState
187	      container.getContainerData().commitSpace();
188	      if (container.getContainerData().getState() == RECOVERING) {
189	        recoveringContainerMap.put(
190	            clock.millis() + recoveringTimeout, containerId);
191	      }
192	      return true;
193	    } else {
194	      LOG.warn("Container already exists with container Id {}", containerId);
195	      throw new StorageContainerException("Container already exists with " +
196	          "container Id " + containerId,
197	          ContainerProtos.Result.CONTAINER_EXISTS);
198	    }
199	  }
